import os, sys

BLUE='\x1b[0;34m'; RESET='\x1b[0m'

def rsplit_file_at_dot(name):
    if name == '..':
        return (name, None)
    i = name.rfind('.')
    if i == -1:
        return (None, name)      # before=None, after=name
    before, after = name[:i], name[i+1:]
    if before == '':
        return (name, None)
    return (before, after)

def stem(name):
    b,a = rsplit_file_at_dot(name)
    return b if b is not None else a

def ext(name):
    b,a = rsplit_file_at_dot(name)
    return a if b is not None else None

def walk(d, prefix, out):
    entries = os.listdir(d)
    n = len(entries)
    for i,name in enumerate(entries):
        last = (i == n-1)
        conn = '└── ' if last else '├── '
        if name == '.jot':
            continue
        full = os.path.join(d,name)
        if os.path.isdir(full):
            out.append(prefix+conn+stem(name))
            walk(full, prefix + ('    ' if last else '│   '), out)
        else:
            e = ext(name)
            if e is None or e == 'md':
                out.append(prefix+conn+BLUE+stem(name)+RESET)

def flat(d, kind):
    entries = os.listdir(d)
    sel=[]
    for name in entries:
        full=os.path.join(d,name)
        if os.path.isdir(full):
            if kind=='folder': sel.append(name)
        else:
            if kind=='note':
                e=ext(name)
                if e is None: return []   # aborts entire listing
                if e=='md': sel.append(name)
    out=[]
    n=len(sel)
    for i,name in enumerate(sel):
        conn = '└── ' if i==n-1 else '├── '
        if kind=='folder': out.append(conn+stem(name))
        else: out.append(conn+BLUE+stem(name)+RESET)
    return out

if __name__=='__main__':
    root=sys.argv[1]; header=sys.argv[2]; mode=sys.argv[3] if len(sys.argv)>3 else 'all'
    out=[header]
    if mode=='all': walk(root,'',out)
    else: out+=flat(root,mode)
    sys.stdout.write('\n'.join(out)+'\n')
